head.script:
	scwin.onpageload = function() {
		imports("uiplugin.popup");		
	};

	scwin.trigger3_onclick = function() {
		console.log("onclick")
		var options = {
			id : "popup3",
			name : "popup3",
			type : "iframePopup",
			width : "500px",
			height : "500px",
			top : "130px",
			left : "800px",
			useATagBtn : true
		};
		$p.openPopup("Popup_useATagBtn_parent_WESD-1262_(WSQ-5233)_sub.xml", options);
	};	

	scwin.trigger8_onclick = function(e) {
		 $p.closePopup("popup3");
	};

scwin.trigger9_onclick = function(e) {
	var tmp = $p.getPopup("popup3").getWindow().input1.getValue();
	console.log("tmp : " +tmp);
	input1.setValue(tmp);
};
